const empreinte = (s) => {
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x85ebca6b) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
};

const trouverId = (m) =>
  m.messageId ??
  m.messageID ??
  m.metadata?.['message-id'] ??
  m.headers?.['message-id'] ??
  null;

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  const brut = m.textPlain ?? m.text ?? m.textHtml ?? '';
  const texte = brut
    .split(/\r?\n(?:>|Le .* a écrit\s*:|On .* wrote:|-{2,}\s*Forwarded)/)[0]
    .replace(/[ \t]*\n[ \t]*/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const from = m.from;
  const expediteur = (
    typeof from === 'string'
      ? (from.match(/<(.+?)>/)?.[1] ?? from)
      : (from?.value?.[0]?.address ?? 'inconnu@exemple.com')
  ).trim().toLowerCase();

  const sujet = (m.subject ?? '(sans objet)').trim();

  const provider_id =
    trouverId(m) ??
    'h:' + empreinte(expediteur + '|' + sujet + '|' + (m.date ?? '') + '|' + texte);

  const refs = [
    m.metadata?.['references'] ?? '',
    m.metadata?.['in-reply-to'] ?? '',
  ].join(' ').match(/<[^>]+>/g) ?? [];

  out.push({ json: { canal: 'email', provider_id, expediteur, sujet, texte, refs } });
}

return out;

const regles = [
  { categorie: 'authentification', priorite: 'haute',
    mots: /mot de passe|connexion|me connecter|identifiant|compte bloqu|acces|accès|login|double authentification|code de verification|code de vérification/i },
  { categorie: 'facturation', priorite: 'haute',
    mots: /factur|preleve|prélèv|rembours|paiement|payer|debite|débité|abonnement|virement/i },
  { categorie: 'panne', priorite: 'haute',
    mots: /panne|erreur|bug|ne fonctionne plus|ne marche plus|tres lent|très lent|indisponible|plantage|charge pas|timeout/i },
  { categorie: 'commercial', priorite: 'basse',
    mots: /offre|devis|tarif|prix|commercial|partenariat|association|remise|essai gratuit/i },
  { categorie: 'information', priorite: 'normale',
    mots: /comment|pouvez-vous|je voudrais savoir|question|renseign|est-il possible/i },
];

const urgence = /urgent|immediat|immédiat|au plus vite|bloque|bloqué|critique|avant vendredi|avant demain|des que possible|dès que possible/i;

const compter = (re, t) => (t.match(new RegExp(re.source, 'gi')) || []).length;

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const cible = ((d.sujet || '') + ' ' + (d.texte || '')).toLowerCase();

  const langue = /[؀-ۿ]/.test(cible) ? 'ar' : 'fr';

  const scores = regles
    .map(r => ({ categorie: r.categorie, priorite: r.priorite, n: compter(r.mots, cible) }))
    .sort((a, b) => b.n - a.n);

  const premier = scores[0] || { n: 0 };
  const second = scores[1] || { n: 0 };

  let categorie = 'autre';
  let priorite = 'normale';
  let confiance = 0;

  if (premier.n > 0) {
    categorie = premier.categorie;
    priorite = premier.priorite;
    confiance = Math.min(0.95, 0.45 + 0.15 * (premier.n - second.n) + 0.05 * premier.n);
  }

  if (urgence.test(cible) && priorite !== 'haute') priorite = 'haute';

  if (langue !== 'fr') { categorie = 'autre'; confiance = 0; }

  const revue = confiance < 0.6 || langue !== 'fr';

  out.push({ json: Object.assign({}, d, {
    categorie: categorie,
    priorite: priorite,
    confiance: Number(confiance.toFixed(3)),
    langue: langue,
    revue: revue,
  }) });
}

return out;

const out = [];

for (const item of $input.all()) {
  const brut = String(item.json.output ?? item.json.text ?? '');
  const ticket = $('Enregistrer le ticket').item.json;

  let p = null;
  const m = brut.match(/\{[\s\S]*\}/);
  if (m) { try { p = JSON.parse(m[0]); } catch (e) { p = null; } }

  const sources = p && Array.isArray(p.sources) ? p.sources.map(String) : [];
  const chunk_ids = p && Array.isArray(p.chunk_ids)
    ? p.chunk_ids.map(Number).filter(function (x) { return Number.isFinite(x); })
    : [];

  const etaye = !!(p && p.etaye === true && chunk_ids.length > 0);

  let texte;
  if (!etaye) {
    texte = 'Information insuffisante : aucune fiche publiee ne couvre cette demande. A traiter par un agent.';
  } else {
    texte = String(p.texte || '').trim() + '\n\nSources : ' + sources.join(' | ');
  }

  out.push({ json: {
    ticket_id: ticket.ticket_id,
    texte: texte,
    etaye: etaye,
    chunk_ids: chunk_ids,
    revue: !etaye,
    agent_brut: brut.slice(0, 2000),
  }});
}

return out;

