  insert into escalations (ticket_id, motif)
  values ($1::bigint, $2::text)
  returning id as escalade_id, ticket_id
),
d as (
  update drafts set statut = 'rejete' where id = $3::bigint returning id as draft_id
)
select e.escalade_id, e.ticket_id, d.draft_id from e, d;

